import os
import hmac
import hashlib
import time
import json
from flask import Flask, request, jsonify, g
from functools import wraps
import psycopg2

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'inventory')
DB_USER = os.environ.get('DB_USER', 'app_user')
DB_PASS = os.environ.get('DB_PASS', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        # Validate API key format (32 hex chars)
        if len(api_key) != 32 or not all(c in '0123456789abcdef' for c in api_key):
            return jsonify({'error': 'Invalid API key format'}), 401
        g.api_key = api_key
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/products/search', methods=['GET'])
@require_api_key
def search_products():
    """Search products by category and optional price range."""
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = request.args.get('sort', 'name')

    # Validate price parameters
    try:
        min_p = float(min_price)
        max_p = float(max_price)
    except ValueError:
        return jsonify({'error': 'Invalid price format'}), 400

    # Whitelist sort columns to prevent injection via ORDER BY
    allowed_sorts = ['name', 'price', 'created_at', 'stock_count']
    if sort_by not in allowed_sorts:
        sort_by = 'name'

    # Build query - category uses parameterized approach for the LIKE clause
    # but constructs the full query with validated sort
    conn = get_db()
    cur = conn.cursor()

    query = f"""SELECT p.id, p.name, p.price, p.stock_count, c.category_name 
               FROM products p 
               JOIN categories c ON p.category_id = c.id 
               WHERE c.category_name LIKE '%' || %s || '%'
               AND p.price BETWEEN %s AND %s
               ORDER BY p.{sort_by} ASC
               LIMIT 50"""

    cur.execute(query, (category, min_p, max_p))
    rows = cur.fetchall()

    results = [{'id': r[0], 'name': r[1], 'price': float(r[2]),
                'stock': r[3], 'category': r[4]} for r in rows]
    return jsonify({'results': results, 'count': len(results)})

@app.route('/api/v2/products/report', methods=['POST'])
@require_api_key
def generate_report():
    """Generate inventory report with custom grouping."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    group_field = data.get('group_by', 'category_name')
    having_clause = data.get('having', '')

    # Attempt to sanitize having clause
    dangerous_keywords = ['DROP', 'DELETE', 'INSERT', 'UPDATE', 'ALTER', 'EXEC']
    for kw in dangerous_keywords:
        if kw.upper() in having_clause.upper():
            return jsonify({'error': 'Invalid filter expression'}), 400

    # Whitelist group fields
    allowed_groups = ['category_name', 'supplier', 'warehouse_location']
    if group_field not in allowed_groups:
        return jsonify({'error': 'Invalid group field'}), 400

    conn = get_db()
    cur = conn.cursor()

    # The HAVING clause is user-controlled - SQL injection vector
    query = f"""SELECT {group_field}, COUNT(*) as cnt, SUM(price * stock_count) as total_value
               FROM products p
               JOIN categories c ON p.category_id = c.id
               GROUP BY {group_field}
               HAVING {having_clause if having_clause else '1=1'}
               ORDER BY total_value DESC"""

    cur.execute(query)
    rows = cur.fetchall()

    results = [{'group': r[0], 'count': r[1], 'total_value': float(r[2])} for r in rows]
    return jsonify({'report': results})

